## 9. The Check-In Loop -- Orchestration

The core loop lives in `AppState` and ties everything together:

```swift
@MainActor
final class AppState: ObservableObject {
    @Published var isMonitoring = true
    @Published var lastMessage: String?
    @Published var isOverlayVisible = false
    @Published var checkInInterval: TimeInterval = 60

    private let screenCapture = ScreenCaptureService()
    private let windowService = ActiveWindowService()
    private let conversationManager = ConversationManager()
    private let panelController = FloatingPanelController()
    private var apiService: ClaudeAPIService?
    private var checkInTask: Task<Void, Never>?

    func startMonitoring() {
        checkInTask = Task {
            while !Task.isCancelled {
                if isMonitoring {
                    await performCheckIn()
                }
                try? await Task.sleep(for: .seconds(checkInInterval))
            }
        }
    }

    private func performCheckIn() async {
        do {
            // 1. Capture screenshot
            let screenshot = try await screenCapture.captureScreen()

            // 2. Get active window context
            let context = windowService.getCurrentContext()

            // 3. Send to Claude API
            guard let api = apiService else { return }
            let response = try await api.sendCheckIn(
                screenshot: screenshot,
                windowContext: context,
                conversationHistory: conversationManager.messagesForAPI(),
                systemPrompt: Settings.systemPrompt
            )

            // 4. Store in conversation history
            // (build the user message that was sent, store it + response)
            conversationManager.addExchange(
                userMessage: /* the user message built by API service */,
                assistantResponse: response
            )

            // 5. Show overlay
            lastMessage = response
            panelController.show(message: response, duration: 10)
        } catch {
            print("Check-in failed: \(error)")
            // Silently skip -- don't spam the user with error overlays
        }
    }
}
```

**Error handling philosophy**: Check-ins that fail (network issues, API errors) are silently skipped. The next interval will try again. This is a background assistant, not a critical service. Log errors for debugging but never show error overlays to the user.

