import AppKit
import SwiftUI

@MainActor
final class FloatingPanelController {
    private var panel: FloatingPanel?
    private var dismissTimer: Timer?

    func show(message: String, duration: TimeInterval = 10.0) {
        let overlayView = ClippyOverlayView(message: message, onDismiss: { [weak self] in
            self?.dismiss()
        })
        let hostingView = NSHostingView(rootView: overlayView)
        hostingView.frame = NSRect(x: 0, y: 0, width: 340, height: 160)

        if panel == nil {
            panel = FloatingPanel(contentView: hostingView)
        } else {
            panel?.contentView = hostingView
        }

        // Fit content
        panel?.setContentSize(hostingView.fittingSize)

        // Position bottom-right of main screen
        if let screen = NSScreen.main {
            let screenFrame = screen.visibleFrame
            let panelSize = panel?.frame.size ?? NSSize(width: 340, height: 160)
            let x = screenFrame.maxX - panelSize.width - 20
            let y = screenFrame.minY + 20
            panel?.setFrameOrigin(NSPoint(x: x, y: y))
        }

        panel?.orderFrontRegardless()
        panel?.alphaValue = 0

        NSAnimationContext.runAnimationGroup { ctx in
            ctx.duration = 0.3
            ctx.timingFunction = CAMediaTimingFunction(name: .easeOut)
            panel?.animator().alphaValue = 1.0
        }

        // Auto-dismiss
        dismissTimer?.invalidate()
        dismissTimer = Timer.scheduledTimer(withTimeInterval: duration, repeats: false) { [weak self] _ in
            Task { @MainActor in
                self?.dismiss()
            }
        }
    }

    func dismiss() {
        dismissTimer?.invalidate()
        dismissTimer = nil

        NSAnimationContext.runAnimationGroup({ ctx in
            ctx.duration = 0.3
            ctx.timingFunction = CAMediaTimingFunction(name: .easeIn)
            panel?.animator().alphaValue = 0
        }, completionHandler: { [weak self] in
            self?.panel?.orderOut(nil)
        })
    }
}

