import ScreenCaptureKit
import CoreGraphics

final class ScreenCaptureService {
    enum CaptureError: Error {
        case noDisplay
        case captureFailed
    }

    func captureScreen() async throws -> CGImage {
        let content = try await SCShareableContent.excludingDesktopWindows(
            false, onScreenWindowsOnly: true
        )

        guard let mainDisplay = content.displays.first else {
            throw CaptureError.noDisplay
        }

        // Exclude our own app from the capture
        let ownApp = content.applications.first {
            $0.bundleIdentifier == Bundle.main.bundleIdentifier
        }
        let excludedApps = ownApp.map { [$0] } ?? []

        let filter = SCContentFilter(
            display: mainDisplay,
            excludingApplications: excludedApps,
            exceptingWindows: []
        )

        let config = SCStreamConfiguration()
        let aspectRatio = CGFloat(mainDisplay.height) / CGFloat(mainDisplay.width)
        config.width = 1092
        config.height = Int(1092.0 * aspectRatio)
        config.showsCursor = false
        config.pixelFormat = kCVPixelFormatType_32BGRA

        let image = try await SCScreenshotManager.captureImage(
            contentFilter: filter,
            configuration: config
        )

        return image
    }

    /// Check if screen recording permission is granted
    func hasPermission() async -> Bool {
        do {
            _ = try await SCShareableContent.excludingDesktopWindows(false, onScreenWindowsOnly: true)
            return true
        } catch {
            return false
        }
    }
}

