import AppKit
import ApplicationServices

final class ActiveWindowService {
    func getCurrentContext() -> WindowContext {
        let app = NSWorkspace.shared.frontmostApplication

        let appName = app?.localizedName ?? "Unknown"
        let bundleId = app?.bundleIdentifier ?? "unknown"
        let windowTitle = frontmostWindowTitle(pid: app?.processIdentifier)

        return WindowContext(
            appName: appName,
            bundleIdentifier: bundleId,
            windowTitle: windowTitle,
            timestamp: Date()
        )
    }

    private func frontmostWindowTitle(pid: pid_t?) -> String? {
        guard let pid else { return nil }

        let appRef = AXUIElementCreateApplication(pid)
        var focusedWindow: CFTypeRef?

        let result = AXUIElementCopyAttributeValue(
            appRef,
            kAXFocusedWindowAttribute as CFString,
            &focusedWindow
        )

        guard result == .success else { return nil }

        var titleValue: CFTypeRef?
        let titleResult = AXUIElementCopyAttributeValue(
            focusedWindow as! AXUIElement,
            kAXTitleAttribute as CFString,
            &titleValue
        )

        guard titleResult == .success, let title = titleValue as? String else { return nil }
        return title
    }

    /// Request accessibility permission (shows system dialog if not granted)
    @discardableResult
    func requestAccessibility() -> Bool {
        let options = [kAXTrustedCheckOptionPrompt.takeUnretainedValue(): true] as CFDictionary
        return AXIsProcessTrustedWithOptions(options)
    }

    /// Check accessibility permission without prompting
    func hasAccessibility() -> Bool {
        return AXIsProcessTrusted()
    }
}

