import Foundation
import CoreGraphics

final class ClaudeAPIService {
    enum APIError: Error, LocalizedError {
        case noAPIKey
        case badResponse(statusCode: Int, body: String)
        case noContent

        var errorDescription: String? {
            switch self {
            case .noAPIKey: return "No API key configured"
            case .badResponse(let code, let body): return "API error \(code): \(body)"
            case .noContent: return "Empty response from Claude"
            }
        }
    }

    private let session = URLSession.shared

    func sendCheckIn(
        screenshot: CGImage,
        windowContext: WindowContext,
        conversationHistory: [ClaudeMessage],
        systemPrompt: String,
        apiKey: String,
        model: String
    ) async throws -> (response: String, userMessage: ClaudeMessage) {
        // Compress screenshot to JPEG base64
        let jpegData = ImageCompressor.compressToJPEG(screenshot, quality: 0.7)
        let base64String = jpegData.base64EncodedString()

        // Build context text
        let formatter = ISO8601DateFormatter()
        let contextText = """
        [Check-in at \(formatter.string(from: Date()))]
        Active app: \(windowContext.appName) (\(windowContext.bundleIdentifier))
        Window title: \(windowContext.windowTitle ?? "N/A")
        """

        let userContent: [ContentBlock] = [
            .image(base64: base64String),
            .text(contextText)
        ]

        let userMessage = ClaudeMessage(role: "user", content: userContent)

        // Build full messages array
        var messages = conversationHistory
        messages.append(userMessage)

        let request = ClaudeRequest(
            model: model,
            max_tokens: 300,
            system: systemPrompt,
            messages: messages
        )

        // Send request
        var urlRequest = URLRequest(url: URL(string: "https://api.anthropic.com/v1/messages")!)
        urlRequest.httpMethod = "POST"
        urlRequest.setValue(apiKey, forHTTPHeaderField: "x-api-key")
        urlRequest.setValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
        urlRequest.setValue("application/json", forHTTPHeaderField: "content-type")
        urlRequest.timeoutInterval = 30

        let encoder = JSONEncoder()
        urlRequest.httpBody = try encoder.encode(request)

        let (data, response) = try await session.data(for: urlRequest)

        guard let httpResponse = response as? HTTPURLResponse else {
            throw APIError.badResponse(statusCode: 0, body: "Not an HTTP response")
        }

        guard httpResponse.statusCode == 200 else {
            let body = String(data: data, encoding: .utf8) ?? "unknown error"
            throw APIError.badResponse(statusCode: httpResponse.statusCode, body: body)
        }

        let claudeResponse = try JSONDecoder().decode(ClaudeResponse.self, from: data)
        guard let text = claudeResponse.text else {
            throw APIError.noContent
        }

        return (response: text, userMessage: userMessage)
    }
}

