import Foundation

final class ConversationManager {
    private let maxHistoryPairs = 10
    private let storageURL: URL
    private(set) var history: [ClaudeMessage] = []

    init() {
        let appSupport = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        ).first!
        let dir = appSupport.appendingPathComponent("ClippyMac", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        storageURL = dir.appendingPathComponent("conversation.json")
        load()
    }

    func addExchange(userMessage: ClaudeMessage, assistantResponse: String) {
        history.append(userMessage)
        history.append(ClaudeMessage(
            role: "assistant",
            content: [.text(assistantResponse)]
        ))

        // Trim to max history
        if history.count > maxHistoryPairs * 2 {
            history = Array(history.suffix(maxHistoryPairs * 2))
        }

        save()
    }

    /// Returns history with old image data stripped to save tokens.
    /// Only the most recent user message retains its image.
    func messagesForAPI() -> [ClaudeMessage] {
        guard !history.isEmpty else { return [] }

        return history.map { message in
            // Only strip images from user messages that aren't the last one
            guard message.role == "user" else { return message }

