final class PermissionService {
    enum PermissionStatus {
        case granted
        case denied
        case unknown
    }

    func checkScreenRecording() async -> PermissionStatus {
        do {
            _ = try await SCShareableContent.excludingDesktopWindows(false, onScreenWindowsOnly: true)
            return .granted
        } catch {
            return .denied
        }
    }

    func checkAccessibility() -> PermissionStatus {
        AXIsProcessTrusted() ? .granted : .denied
    }

    /// Prompt for accessibility permission (shows system dialog)
    func requestAccessibility() {
        let options = [kAXTrustedCheckOptionPrompt.takeUnretainedValue(): true] as CFDictionary
        AXIsProcessTrustedWithOptions(options)
    }

    /// Trigger screen recording permission by attempting a capture
    func requestScreenRecording() async {
        _ = try? await SCShareableContent.excludingDesktopWindows(false, onScreenWindowsOnly: true)
    }
}

