import SwiftUI
import CoreGraphics

@MainActor
final class AppState: ObservableObject {
    @Published var isMonitoring = false
    @Published var lastMessage: String?
    @Published var isOverlayVisible = false
    @Published var checkInCount = 0
    @Published var lastError: String?

    let screenCapture = ScreenCaptureService()
    let windowService = ActiveWindowService()
    let conversationManager = ConversationManager()
    let permissionService = PermissionService()
    let panelController = FloatingPanelController()
    private let apiService = ClaudeAPIService()
    private let settings = AppSettings.shared
    private var checkInTask: Task<Void, Never>?

    var hasAPIKey: Bool {
        KeychainHelper.load() != nil
    }

    init() {
        // Auto-start if API key is configured
        if hasAPIKey {
            startMonitoring()
        }
    }

    func startMonitoring() {
        guard checkInTask == nil else { return }
        isMonitoring = true

        checkInTask = Task {
            // Initial delay before first check-in
            try? await Task.sleep(for: .seconds(5))

            while !Task.isCancelled {
                if isMonitoring {
                    // Skip if user is idle
                    let idleTime = CGEventSource.secondsSinceLastEventType(
                        .combinedSessionState,
                        eventType: .mouseMoved
                    )
                    if idleTime < settings.idleThreshold {
                        await performCheckIn()
                    }
                }
                try? await Task.sleep(for: .seconds(settings.checkInInterval))
            }
        }
    }

    func stopMonitoring() {
        checkInTask?.cancel()
        checkInTask = nil
        isMonitoring = false
    }

    func performCheckIn() async {
        guard let apiKey = KeychainHelper.load() else {
            lastError = "No API key configured. Open Settings to add one."
            return
        }

        do {
            let screenshot = try await screenCapture.captureScreen()
            let context = windowService.getCurrentContext()

            let (response, userMessage) = try await apiService.sendCheckIn(
                screenshot: screenshot,
                windowContext: context,
                conversationHistory: conversationManager.messagesForAPI(),
                systemPrompt: settings.systemPrompt,
                apiKey: apiKey,
                model: settings.model
            )

            conversationManager.addExchange(
                userMessage: userMessage,
                assistantResponse: response
            )

            lastMessage = response
            lastError = nil
            checkInCount += 1

            panelController.show(
                message: response,
                duration: settings.autoDismissTime
            )
        } catch {
            lastError = error.localizedDescription
            print("Check-in failed: \(error)")
        }
    }
}

