import SwiftUI
import ServiceManagement

struct SettingsView: View {
    @ObservedObject var appState: AppState
    @State private var apiKey: String = ""
    @State private var showingAPIKey = false
    @State private var interval: Double = 60
    @State private var selectedModel = "claude-sonnet-4-20250514"
    @State private var dismissTime: Double = 10
    @State private var systemPrompt: String = ""
    @State private var screenPermission = false
    @State private var accessibilityPermission = false

    private let settings = AppSettings.shared

    private let models = [
        ("claude-haiku-4-5-20251001", "Haiku 4.5 (~$0.37/day)"),
        ("claude-sonnet-4-20250514", "Sonnet 4 (~$3.70/day)"),
        ("claude-opus-4-20250514", "Opus 4 (~$37/day)")
    ]

    var body: some View {
        TabView {
            generalTab
                .tabItem { Label("General", systemImage: "gear") }

            permissionsTab
                .tabItem { Label("Permissions", systemImage: "lock.shield") }

            personalityTab
                .tabItem { Label("Personality", systemImage: "face.smiling") }
        }
        .frame(width: 480, height: 400)
        .onAppear {
            loadSettings()
        }
    }

    private var generalTab: some View {
        Form {
            Section("API Key") {
                HStack {
                    if showingAPIKey {
                        TextField("sk-ant-...", text: $apiKey)
                            .textFieldStyle(.roundedBorder)
                    } else {
                        SecureField("sk-ant-...", text: $apiKey)
                            .textFieldStyle(.roundedBorder)
                    }
                    Button(showingAPIKey ? "Hide" : "Show") {
                        showingAPIKey.toggle()
                    }
                    Button("Save") {
                        try? KeychainHelper.save(apiKey: apiKey)
                        if !appState.isMonitoring {
                            appState.startMonitoring()
                        }
                    }
                    .disabled(apiKey.isEmpty)
                }
            }

            Section("Model") {
                Picker("Claude Model", selection: $selectedModel) {
                    ForEach(models, id: \.0) { model in
                        Text(model.1).tag(model.0)
                    }
                }
                .onChange(of: selectedModel) { _, newValue in
                    settings.model = newValue
                }
            }

            Section("Timing") {
                HStack {
                    Text("Check-in every")
                    Slider(value: $interval, in: 30...300, step: 10) {
                        Text("Interval")
                    }
                    Text("\(Int(interval))s")
                        .monospacedDigit()
                        .frame(width: 40)
                }
                .onChange(of: interval) { _, newValue in
                    settings.checkInInterval = newValue
                }

                HStack {
                    Text("Auto-dismiss after")
                    Slider(value: $dismissTime, in: 5...30, step: 1) {
                        Text("Dismiss")
                    }
                    Text("\(Int(dismissTime))s")
                        .monospacedDigit()
                        .frame(width: 40)
                }
                .onChange(of: dismissTime) { _, newValue in
                    settings.autoDismissTime = newValue
                }
            }

            Section("Startup") {
                Toggle("Launch at login", isOn: Binding(
                    get: { settings.launchAtLogin },
                    set: { newValue in
                        settings.launchAtLogin = newValue
                        if newValue {
                            try? SMAppService.mainApp.register()
                        } else {
                            try? SMAppService.mainApp.unregister()
                        }
                    }
                ))
            }
        }
        .padding()
    }

    private var permissionsTab: some View {
        Form {
            Section("Required Permissions") {
                HStack {
                    Image(systemName: screenPermission ? "checkmark.circle.fill" : "xmark.circle")
                        .foregroundStyle(screenPermission ? .green : .red)
                    Text("Screen Recording")
                    Spacer()
                    if !screenPermission {
                        Button("Grant") {
                            Task {
                                await appState.permissionService.requestScreenRecording()
                                screenPermission = await appState.permissionService.checkScreenRecording() == .granted
                            }
                        }
                    }
                }

                HStack {
                    Image(systemName: accessibilityPermission ? "checkmark.circle.fill" : "xmark.circle")
                        .foregroundStyle(accessibilityPermission ? .green : .red)
                    Text("Accessibility")
                    Spacer()
                    if !accessibilityPermission {
                        Button("Grant") {
                            appState.permissionService.requestAccessibility()
                            accessibilityPermission = appState.permissionService.checkAccessibility() == .granted
                        }
                    }
                }
            }

            Section {
                Text("Screen Recording lets Clippy see your screen. Accessibility lets Clippy read window titles for context.")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }

            Section {
                Button("Open System Settings") {
                    NSWorkspace.shared.open(URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy")!)
                }
            }
        }
        .padding()
        .task {
            screenPermission = await appState.permissionService.checkScreenRecording() == .granted
            accessibilityPermission = appState.permissionService.checkAccessibility() == .granted
        }
    }

    private var personalityTab: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text("System Prompt")
                .font(.headline)

            TextEditor(text: $systemPrompt)
                .font(.system(size: 12, design: .monospaced))
                .frame(maxHeight: .infinity)
                .border(Color.secondary.opacity(0.3))

            HStack {
                Button("Reset to Default") {
                    systemPrompt = AppSettings.defaultSystemPrompt
                    settings.systemPrompt = systemPrompt
                }

                Spacer()

                Button("Save") {
                    settings.systemPrompt = systemPrompt
                }
                .buttonStyle(.borderedProminent)
            }
        }
        .padding()
    }

    private func loadSettings() {
        apiKey = KeychainHelper.load() ?? ""
        interval = settings.checkInInterval
        selectedModel = settings.model
        dismissTime = settings.autoDismissTime
        systemPrompt = settings.systemPrompt
    }
}

